INSERT INTO "metric_definitions" VALUES('capital_expenditures','Capital expenditures','["capex", "capital expenditure", "capital expenditures", "purchases of property and equipment", "additions to property and equipment", "purchases of property, plant and equipment", "property and equipment additions", "investments in property and equipment", "us-gaap:PaymentsToAcquirePropertyPlantAndEquipment"]','USD_millions','Cash outflows for purchases of property, plant, and equipment. Typically reported in the investing activities section of the cash flow statement. This is the headline capex figure.');
INSERT INTO "metric_definitions" VALUES('depreciation_amortization','Depreciation and amortization','["d&a", "depreciation", "depreciation and amortization", "depreciation, amortization and accretion", "depreciation and amortization expense", "us-gaap:DepreciationDepletionAndAmortization"]','USD_millions','Non-cash charge reflecting the periodic expense of long-lived assets. Often reported alongside capex as a proxy for asset base turnover.');
INSERT INTO "metric_definitions" VALUES('property_plant_equipment_net','Property, plant and equipment, net','["ppe", "pp&e", "property and equipment net", "property, plant and equipment, net", "net property and equipment", "us-gaap:PropertyPlantAndEquipmentNet"]','USD_millions','Balance sheet carrying value of long-lived tangible assets after accumulated depreciation. The stock companion to capex (flow) and D&A (flow).');
INSERT INTO "metric_definitions" VALUES('revenue','Total revenue','["revenue", "total revenue", "net revenue", "net sales", "total net sales", "revenues", "us-gaap:Revenues"]','USD_millions','Top-line revenue for the reporting period. Used as the denominator in the capex/revenue efficiency ratio.');
INSERT INTO "metric_definitions" VALUES('operating_cash_flow','Net cash provided by operating activities','["ocf", "operating cash flow", "cash from operations", "cash flow from operations", "net cash provided by operating activities", "net cash from operating activities", "us-gaap:NetCashProvidedByOperatingActivities"]','USD_millions','Cash generated by the business''s core operations before investing or financing activity. Used as the denominator in the capex/OCF efficiency ratio.');
INSERT INTO "metric_definitions" VALUES('cloud_segment_revenue','Cloud/datacenter segment revenue','["cloud revenue", "cloud segment revenue", "datacenter revenue", "cloud segment"]','USD_millions','Revenue from cloud computing / datacenter operations. For hyperscalers with named segments, this is the segment revenue (e.g. MSFT "Intelligent Cloud", AMZN "AWS"). For pure-play neoclouds, total revenue serves as the proxy. See data/seeds/coverage.yaml for per-company segment treatment.');
